function env(name) {
  try { return $env[name] || ''; } catch (e) { return ''; }  // n8n 2.x blocks $env in Code nodes unless N8N_BLOCK_ENV_ACCESS_IN_NODE=false
}
// Settings: edit the defaults here, or set the INBOX_AGENT_* environment variables (see n8n/README.md).
const settings = {
  agent_url: (env('INBOX_AGENT_URL') || 'https://davutkursun-inbox-agent.hf.space').replace(/\/+$/, ''),
  decision_url: env('INBOX_AGENT_DECISION_URL') || 'http://localhost:5678/webhook/inbox-agent-decision',
  decision_token: env('INBOX_AGENT_DECISION_TOKEN'),
  telegram_chat_id: env('INBOX_AGENT_TELEGRAM_CHAT_ID'),
};
const MAX_CHARS = 2000;  // the agent refuses longer bodies with 413
return $input.all().map((item) => {
  const j = item.json;
  const from = j.from?.value?.[0]?.address || j.from?.text || j.From || j.from || '';
  const subject = String(j.subject || j.Subject || '').slice(0, 300);
  const body = String(j.text || j.textPlain || j.body || j.snippet || '').trim().slice(0, MAX_CHARS);
  return { json: { ...settings, email: { from: String(from), subject, body } } };
});

// One item per queued action, with Approve / Reject links that open the decision webhook below.
const s = $('Normalize email').first().json;
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  for (const a of r.actions_pending || []) {
    const link = (decision) => `${s.decision_url}?action_id=${encodeURIComponent(a.action_id)}&decision=${decision}`
      + (s.decision_token ? `&token=${encodeURIComponent(s.decision_token)}` : '');
    const args = Object.entries(a.args || {}).map(([k, v]) => `${k}=${v}`).join(', ');
    const message = [
      `<b>Approval needed</b>: ${esc(a.tool)} (${esc(args)})`,
      `From ${esc(a.customer_email)}, intent ${esc(r.intent)}`,
      `Summary: ${esc(r.summary)}`,
      r.draft_reply ? `Draft reply: ${esc(r.draft_reply.subject)}` : '',
      `<a href="${esc(link('approve'))}">Approve</a> | <a href="${esc(link('reject'))}">Reject</a>`,
    ].filter(Boolean).join('\n');
    out.push({ json: { action_id: a.action_id, tool: a.tool, thread_id: r.thread_id, customer_email: a.customer_email,
                       telegram_chat_id: s.telegram_chat_id, approve_url: link('approve'), reject_url: link('reject'), message } });
  }
}
return out;

function env(name) {
  try { return $env[name] || ''; } catch (e) { return ''; }  // n8n 2.x blocks $env in Code nodes unless N8N_BLOCK_ENV_ACCESS_IN_NODE=false
}
// Validates the clicked link before anything reaches the agent: a known decision, a well-formed id, the shared token.
const AGENT_URL = (env('INBOX_AGENT_URL') || 'https://davutkursun-inbox-agent.hf.space').replace(/\/+$/, '');
const TOKEN = env('INBOX_AGENT_DECISION_TOKEN');
const q = $input.first().json.query || {};
if (!['approve', 'reject'].includes(q.decision)) throw new Error('decision must be approve or reject');
if (!/^act_[a-f0-9]{10}$/.test(q.action_id || '')) throw new Error('malformed action_id');
if (TOKEN && q.token !== TOKEN) throw new Error('wrong or missing token');
return [{ json: { action_id: q.action_id, decision: q.decision, url: `${AGENT_URL}/${q.decision}/${q.action_id}` } }];
